package com.example.craftanything;

import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.inventory.*; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import java.util.*;

public final class RecipeEditor implements Listener {
 private final CraftAnythingPlugin plugin; private final RecipeStore store; private final Map<UUID,String> sessions=new HashMap<>();
 RecipeEditor(CraftAnythingPlugin p,RecipeStore s){plugin=p;store=s;}
 public void open(Player p,String name){Inventory inv=Bukkit.createInventory(p,27,ChatColor.DARK_GRAY+"Craft Anything: "+name); sessions.put(p.getUniqueId(),name); ItemStack glass=button(Material.GRAY_STAINED_GLASS_PANE,"§r","§7This slot is locked"); for(int i=0;i<27;i++)inv.setItem(i,glass); int[] grid={0,1,2,9,10,11,18,19,20}; for(int slot:grid)inv.setItem(slot,null); RecipeData old=store.get(name); if(old==null)inv.setItem(14,button(Material.PAPER,"§eRESULT","§7Put the output item here")); else {for(int i=0;i<9;i++)inv.setItem(grid[i],old.ingredients()[i]==null?null:old.ingredients()[i].clone());inv.setItem(14,old.result().clone());} inv.setItem(25,button(Material.RED_CONCRETE,"§cDECLINE","§7Cancel and return items")); inv.setItem(26,button(Material.LIME_CONCRETE,"§aACCEPT","§7Save this recipe")); p.openInventory(inv);}
 private ItemStack button(Material m,String n,String lore){ItemStack i=new ItemStack(m);ItemMeta x=i.getItemMeta();x.setDisplayName(n);x.setLore(List.of(lore));i.setItemMeta(x);return i;}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!sessions.containsKey(p.getUniqueId()))return; if(!e.getView().getTitle().startsWith(ChatColor.DARK_GRAY+"Craft Anything:"))return; int slot=e.getRawSlot(); boolean top=slot>=0&&slot<27; if(!top&&e.isShiftClick()){e.setCancelled(true); ItemStack moving=e.getCurrentItem(); if(moving!=null&&!moving.getType().isAir()){for(int target:new int[]{0,1,2,9,10,11,18,19,20})if(e.getInventory().getItem(target)==null){e.getInventory().setItem(target,moving.clone());e.getClickedInventory().setItem(e.getSlot(),null);break;}}return;} if(top&&!isEditable(slot))e.setCancelled(true); if(!top&&(e.getClick().isKeyboardClick()||e.getClick()==org.bukkit.event.inventory.ClickType.DOUBLE_CLICK))e.setCancelled(true); if(slot==25){e.setCancelled(true);returnItems(p,e.getInventory());p.closeInventory();sessions.remove(p.getUniqueId());p.playSound(p,Sound.BLOCK_NOTE_BLOCK_BASS,1,0.7f);return;} if(slot==14&&isPlaceholder(e.getCurrentItem())){e.setCancelled(true);ItemStack cursor=e.getCursor();if(cursor!=null&&!cursor.getType().isAir()){e.getInventory().setItem(14,cursor.clone());e.setCursor(null);}else e.getInventory().setItem(14,null);p.updateInventory();return;} if(slot!=26)return; e.setCancelled(true); ItemStack result=e.getInventory().getItem(14); if(result==null||result.getType().isAir()||isPlaceholder(result)){p.sendMessage("§cPlace a result item in the result slot first.");return;} ItemStack[] in=new ItemStack[9];for(int i=0;i<9;i++)in[i]=e.getInventory().getItem(new int[]{0,1,2,9,10,11,18,19,20}[i]); store.save(new RecipeData(sessions.get(p.getUniqueId()),in,result.clone()));store.registerBukkitRecipes();p.closeInventory();sessions.remove(p.getUniqueId());p.playSound(p,Sound.BLOCK_ANVIL_USE,1,1);p.sendMessage("§aRecipe saved! Use it in a crafting table.");}
 @EventHandler public void close(InventoryCloseEvent e){if(e.getPlayer() instanceof Player p&&sessions.containsKey(p.getUniqueId())){returnItems(p,e.getInventory());sessions.remove(p.getUniqueId());}}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getWhoClicked() instanceof Player p&&sessions.containsKey(p.getUniqueId())){for(int slot:e.getRawSlots())if(slot<27&&!isEditable(slot)){e.setCancelled(true);return;}}}
 private boolean isEditable(int slot){return slot==14||java.util.Arrays.stream(new int[]{0,1,2,9,10,11,18,19,20}).anyMatch(x->x==slot);}
 private boolean isPlaceholder(ItemStack item){return item!=null&&item.getType()==Material.PAPER&&item.hasItemMeta()&&"§eRESULT".equals(item.getItemMeta().getDisplayName());}
 private void returnItems(Player p,Inventory i){for(int s:new int[]{0,1,2,9,10,11,18,19,20})give(p,i.getItem(s));give(p,i.getItem(14));}
 private void give(Player p,ItemStack i){if(i!=null&&!i.getType().isAir())p.getInventory().addItem(i);}
}
